package uk.ac.ravensbourne.casevault.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.http.HttpHeaders; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
/** Applies both IP and submitted-account buckets before authentication work (CWE-770). */
@Component public class LoginRateLimitFilter extends OncePerRequestFilter { private final LoginRateLimiter limiter; public LoginRateLimitFilter(LoginRateLimiter l){limiter=l;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {if("POST".equals(r.getMethod())&&"/login".equals(r.getServletPath())){var decision=limiter.consume(r.getRemoteAddr(),r.getParameter("username"));if(!decision.allowed()){s.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());s.setHeader(HttpHeaders.RETRY_AFTER,Long.toString(decision.retryAfterSeconds()));return;}}c.doFilter(r,s);} }
